def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_d = 0
    cc = 0
    for i in range(n):
        if op[i] == 'D':
            opp_d += 1
        if my[i] == 'C' and op[i] == 'C':
            cc += 1
    opp_c = n - opp_d

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if my[i] == 'D':
            my_d_streak += 1
        else:
            break

    opp_d5 = sum(1 for i in range(max(0, n - 5), n) if op[i] == 'D')

    if (opp_d_streak >= 3 and cc <= 1) or (opp_d_streak >= 4 and cc <= 2):
        return 'D'
    if opp_d_streak >= 6 and cc <= max(2, n // 20):
        return 'D'
    if opp_c <= max(1, n // 20) and opp_d * 10 >= n * 8:
        return 'D'
    if opp_d5 >= 4 and cc <= max(2, n // 10) and opp_c <= max(3, n // 4):
        return 'D'
    if opp_d_streak >= 3 and my_d_streak >= 3 and cc <= max(4, n // 20):
        return 'D'

    opps = 0
    puns = 0
    rec_opps = 0
    rec_puns = 0
    rec_start = max(1, n - 15)

    for i in range(1, n):
        if my[i - 1] == 'D':
            opps += 1
            if op[i] == 'D':
                puns += 1
            if i >= rec_start:
                rec_opps += 1
                if op[i] == 'D':
                    rec_puns += 1

    exploit = False
    if opps >= 1 and puns == 0 and opp_d <= max(1, n // 4) and opp_d_streak <= 1:
        exploit = True
    if rec_opps >= 1 and rec_puns == 0 and opp_d <= max(2, n // 3) and opp_c > max(2, n // 5):
        exploit = True
    if opps >= 4 and puns * 3 <= opps and opp_d <= max(2, n // 3) and opp_c > max(2, n // 5):
        exploit = True

    last_opp = op[-1]

    if exploit:
        if last_opp == 'C':
            return 'D'
        if n >= 2 and my[-2] == 'D':
            if opp_d_streak <= 2 or cc > max(5, n // 5):
                return 'C'
            return 'D'
        if opp_d_streak >= 3 and cc <= max(2, n // 10):
            return 'D'
        return 'D'

    if n <= 3 and last_opp == 'D':
        return 'D'

    if opp_d == 0 and n >= 10 and n <= 12:
        good = True
        k = min(5, n)
        for i in range(n - k, n):
            if my[i] != 'C' or op[i] != 'C':
                good = False
                break
        if good:
            return 'D'

    if opp_d <= max(1, n // 10) and (n == 25 or n == 50):
        good = True
        k = min(4, n)
        for i in range(n - k, n):
            if my[i] != 'C' or op[i] != 'C':
                good = False
                break
        if good:
            return 'D'

    if last_opp == 'D':
        if n >= 2 and my[-2] == 'D':
            if opp_d_streak <= 2 or cc >= max(3, n // 10):
                return 'C'
            return 'D'
        return 'D'

    return 'C'
